const loadPdfModule = async () => {
  try {
    const imported = await import('pdf-parse')
    return imported.default || imported
  } catch (error) {
    throw new Error('Failed to load pdf-parse module. Install it in your n8n instance (npm install pdf-parse).')
  }
}
const pdfParse = await loadPdfModule()
const sanitizeText = text => {
  if (typeof text !== 'string') {
    return ''
  }
  return text
    .replace(/
/g, '
')
    .replace(//g, '
')
    .replace(/�/g, '')
    .replace(/[-	-]+/g, ' ')
    .replace(/[	 \v]+/g, ' ')
    .replace(/[^\S
]+/g, ' ')
    .replace(/
{3,}/g, '

')
    .trim()
}
const buildPrompt = ({ emailMetadata, documentText, summary }) => {
  const metadataLines = []
  if (emailMetadata.source) metadataLines.push(`Source: ${emailMetadata.source}`)
  if (emailMetadata.emailDate) metadataLines.push(`Email-Date: ${emailMetadata.emailDate}`)
  if (emailMetadata.attachmentName) metadataLines.push(`Attachment: ${emailMetadata.attachmentName}`)
  if (emailMetadata.mimeType) metadataLines.push(`Mime-Type: ${emailMetadata.mimeType}`)
  if (Array.isArray(emailMetadata.matchedSupplierEmails) && emailMetadata.matchedSupplierEmails.length) {
    metadataLines.push(`Matched-Suppliers: ${emailMetadata.matchedSupplierEmails.join(', ')}`)
  }
  if (Array.isArray(emailMetadata.allowedSupplierEmails) && emailMetadata.allowedSupplierEmails.length) {
    metadataLines.push(`Allowlist: ${emailMetadata.allowedSupplierEmails.join(', ')}`)
  }
  if (summary.pageCount !== undefined) {
    metadataLines.push(`PDF-Pages: ${summary.pageCount}`)
  }
  if (summary.wordCount !== undefined) {
    metadataLines.push(`PDF-Words: ${summary.wordCount}`)
  }
  const header = metadataLines.length ? metadataLines.join('
') : 'No additional email metadata provided.'
  return `You are an autonomous finance assistant that extracts structured data from European invoices.
Analyse the provided invoice text and reply with a strict JSON object using camelCase keys.
Required JSON schema:
{
  \"issueDate\": string | null,
  \"total\": number | null,
  \"currency\": string | null,
  \"supplierTaxId\": string | null,
  \"customerTaxId\": string | null,
  \"invoiceNumber\": string | null,
  \"paymentReference\": string | null,
  \"lineItems\": [
    {
      \"description\": string | null,
      \"quantity\": number | null,
      \"unitPrice\": number | null,
      \"total\": number | null
    }
  ]
}.
Only include fields listed above. Use null when a value is missing.
Do not add additional commentary.

Email metadata:
${header}

Invoice text:
${documentText}`
}
const results = []
for (const item of items) {
  const metadata = item.json?.emailMetadata || {}
  const binaryData = item.binary?.data?.data
  if (!binaryData) {
    results.push({ json: { emailMetadata: metadata, documentText: '', agentPrompt: buildPrompt({ emailMetadata: metadata, documentText: '', summary: {} }), parserNotes: { warning: 'Attachment binary payload missing or empty.' } } })
    continue
  }
  try {
    const buffer = Buffer.from(binaryData, 'base64')
    const parsed = await pdfParse(buffer)
    const cleanText = sanitizeText(parsed?.text || '')
    const summary = {
      pageCount: typeof parsed?.numpages === 'number' ? parsed.numpages : undefined,
      wordCount: cleanText ? cleanText.split(/\s+/).filter(Boolean).length : 0
    }
    results.push({
      json: {
        emailMetadata: metadata,
        documentText: cleanText,
        agentPrompt: buildPrompt({ emailMetadata: metadata, documentText: cleanText, summary }),
        parserNotes: { summary }
      }
    })
  } catch (error) {
    results.push({
      json: {
        emailMetadata: metadata,
        documentText: '',
        agentPrompt: buildPrompt({ emailMetadata: metadata, documentText: '', summary: {} }),
        parserNotes: { error: error.message || String(error) }
      }
    })
  }
}
return results

const now = new Date().toISOString()
return items.map(item => {
  const parserResult = item.json.parserResult || {}
  const metadata = item.json.emailMetadata || {}
  const safeNumber = value => {
    if (value === undefined || value === null || value === '') {
      return null
    }
    const numeric = Number(value)
    return Number.isNaN(numeric) ? null : numeric
  }
  const normalizeLineItems = Array.isArray(parserResult.lineItems) ? parserResult.lineItems : []
  const allowedSupplierEmails = Array.isArray(metadata.allowedSupplierEmails) ? metadata.allowedSupplierEmails : []
  const matchedSupplierEmails = Array.isArray(metadata.matchedSupplierEmails) ? metadata.matchedSupplierEmails : []
  const primarySupplierEmail = metadata.primarySupplierEmail || matchedSupplierEmails[0] || null
  return {
    json: {
      messageId: metadata.messageId || '',
      threadId: metadata.threadId || '',
      source: metadata.source || '',
      emailSnippet: metadata.snippet || '',
      emailDate: metadata.emailDate || '',
      attachmentName: metadata.attachmentName || '',
      mimeType: metadata.mimeType || '',
      issueDate: parserResult.issueDate || metadata.emailDate || '',
      total: safeNumber(parserResult.total),
      currency: parserResult.currency || null,
      supplierTaxId: parserResult.supplierTaxId || null,
      customerTaxId: parserResult.customerTaxId || null,
      invoiceNumber: parserResult.invoiceNumber || null,
      paymentReference: parserResult.paymentReference || null,
      lineItems: normalizeLineItems.map(item => ({
        description: item.description || '',
        quantity: safeNumber(item.quantity),
        unitPrice: safeNumber(item.unitPrice),
        total: safeNumber(item.total)
      })),
      rawParserResponse: parserResult,
      supplierAllowlistEnforced: Boolean(metadata.supplierAllowlistEnforced),
      allowedSupplierEmails,
      matchedSupplierEmails,
      primarySupplierEmail,
      createdAt: now,
      updatedAt: now
    }
  }
})

const extractJson = output => {
  if (output === undefined || output === null) {
    return {}
  }
  if (typeof output === 'object') {
    return output
  }
  const text = String(output).trim()
  if (!text) {
    return {}
  }
  const tryParse = candidate => {
    try {
      return JSON.parse(candidate)
    } catch (error) {
      return null
    }
  }
  const direct = tryParse(text)
  if (direct && typeof direct === 'object') {
    return direct
  }
  const firstBrace = text.indexOf('{')
  const lastBrace = text.lastIndexOf('}')
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    const sliced = text.slice(firstBrace, lastBrace + 1)
    const parsed = tryParse(sliced)
    if (parsed && typeof parsed === 'object') {
      return parsed
    }
  }
  return { raw: text }
}
return items.map(item => {
  const output = item.json?.output ?? item.json
  const parsed = extractJson(output)
  const intermediateSteps = Array.isArray(item.json?.intermediateSteps) ? item.json.intermediateSteps : []
  return {
    json: {
      parserResult: parsed,
      agentDebug: {
        intermediateSteps,
        rawOutput: output
      }
    }
  }
})
